 * Tests of PayOrder (legacy PAGOORD + PAGODEB), RULE-007 .. RULE-015.
 *
 * NOTE: the copybooks ORDREG / CTAREG are not available, so the status codes of a pending order
 * and of an active account are taken as 'P' and 'A' in the fixtures. Only the paid code 'G' is
 * documented in the design. Any status different from these is treated as "not pending"/"not active".
 */
class PayOrderServiceTest {

    private static final String PENDING = "P";
    private static final String PAID = "G";
    private static final String ACTIVE = "A";
    private static final String INACTIVE = "I";
    private static final String NO_KEY = "      ";

    /** In-memory fakes of the three ports, recording every call in order. */
    static class Fixture {
        final List<String> events = new ArrayList<>();
        final Map<String, Order> orders = new HashMap<>();
        final Map<Long, Account> accounts = new HashMap<>();
        long movementNumber = 9000000001L;
        RuntimeException movementFailure = null;

        Fixture() {
            orders.put("1234567/10",
                    new Order(1234567, 10, PENDING, new BigDecimal("1000.00"), null, null));
            accounts.put(1000123L,
                    new Account(1000123L, "CTE", new BigDecimal("5000.00"), ACTIVE));
        }

        Fixture order(int number, int company, String status, String value) {
            orders.put(number + "/" + company,
                    new Order(number, company, status, new BigDecimal(value), null, null));
            return this;
        }

        Fixture account(long number, String type, String balance, String status) {
            accounts.put(number, new Account(number, type, new BigDecimal(balance), status));
            return this;
        }

        PayOrderService service() {
            OrderRepository orderRepository = new OrderRepository() {
                @Override
                public Optional<Order> findByKeyForUpdate(Integer orderNumber, Integer companyNumber) {
                    events.add("readOrder:" + orderNumber + ":" + companyNumber);
                    return Optional.ofNullable(orders.get(orderNumber + "/" + companyNumber));
                }

                @Override
                public void markPaid(Integer orderNumber, Integer companyNumber,
                                     Long movementNumber, BigDecimal commission) {
                    events.add("markPaid:" + orderNumber + ":" + companyNumber + ":"
                            + movementNumber + ":" + commission.toPlainString());
                }
            };
            AccountRepository accountRepository = new AccountRepository() {
                @Override
                public Optional<Account> findByNumberForUpdate(Long accountNumber) {
                    events.add("readAccount:" + accountNumber);
                    return Optional.ofNullable(accounts.get(accountNumber));
                }

                @Override
                public void updateBalance(Long accountNumber, BigDecimal balance) {
                    events.add("updateBalance:" + accountNumber + ":" + balance.toPlainString());
                }
            };
            MovementGateway movementGateway = orderNumber -> {
                events.add("movement:" + orderNumber);
                if (movementFailure != null) {
                    throw movementFailure;
                }
                return movementNumber;
            };
            return new PayOrderService(orderRepository, accountRepository, movementGateway);
        }

        boolean hasEventStartingWith(String prefix) {
            return events.stream().anyMatch(e -> e.startsWith(prefix));
        }
    }

    private static PayOrderRequest request(String orderNumber, Integer company, String accountType,
                                           Long account, String amount, String channel, String key) {
        return new PayOrderRequest(orderNumber, company, accountType, account,
                amount == null ? null : new BigDecimal(amount), channel, key);
    }

    private static PayOrderRequest validWeb() {
        return request("1234567", 10, "CTE", 1000123L, "1000.00", "WEB", NO_KEY);
    }

    private static PayOrderRequest validOfi() {
        return request("1234567", 10, "CTE", 1000123L, "1000.00", "OFI", "ABC123");
    }

    private static BusinessError rejected(Fixture fx, PayOrderRequest request) {
        Throwable t = catchThrowable(() -> fx.service().execute(request));
        assertThat(t).isInstanceOf(BusinessError.class);
        return (BusinessError) t;
    }

    private static void assertRejected(Fixture fx, PayOrderRequest request,
                                       String code, String legacyCode, String message) {
        BusinessError e = rejected(fx, request);
        assertThat(e.code()).isEqualTo(code);
        assertThat(e.legacyCode()).isEqualTo(legacyCode);
        assertThat(e.getMessage()).isEqualTo(message);
    }

    private static void assertNothingRead(Fixture fx) {
        assertThat(fx.events).isEmpty();
    }

    private static void assertNoWrites(Fixture fx) {
        assertThat(fx.hasEventStartingWith("updateBalance")).isFalse();
        assertThat(fx.hasEventStartingWith("movement")).isFalse();
        assertThat(fx.hasEventStartingWith("markPaid")).isFalse();
    }

