    @Test
    void rule007_order_number_is_zero() {
        Fixture fx = new Fixture();
        assertRejected(fx, request("0000000", 10, "CTE", 1000123L, "1000.00", "WEB", NO_KEY),
                "INVALID_ORDER_NUMBER", "HAY-ERROR", "NUMERO DE ORDEN INVALIDO");
        assertNothingRead(fx);
    }

    @Test
    void rule007_order_number_contains_letters() {
        Fixture fx = new Fixture();
        assertRejected(fx, request("12A4567", 10, "CTE", 1000123L, "1000.00", "WEB", NO_KEY),
                "INVALID_ORDER_NUMBER", "HAY-ERROR", "NUMERO DE ORDEN INVALIDO");
        assertNothingRead(fx);
    }

    @Test
    void rule007_order_number_blank_is_not_numeric() {
        Fixture fx = new Fixture();
