                request("0001234", 10, "CTE", 1000123L, "1000.00", "WEB", NO_KEY));
        assertThat(fx.events.get(0)).isEqualTo("readOrder:1234:10");
        assertThat(response.orderNumber()).isEqualTo(1234);
    }

    @Test
    void rule007_order_number_error_wins_over_account_type_channel_and_key_errors() {
        Fixture fx = new Fixture();
        assertRejected(fx, request("0000000", 10, "XYZ", 1000123L, "1000.00", "ATM", NO_KEY),
                "INVALID_ORDER_NUMBER", "HAY-ERROR", "NUMERO DE ORDEN INVALIDO");
        assertNothingRead(fx);
    }

    // ---------------------------------------------------------------- RULE-008

    @Test
    void rule008_unknown_account_type_is_rejected() {
        Fixture fx = new Fixture();
        assertRejected(fx, request("1234567", 10, "XYZ", 1000123L, "1000.00", "WEB", NO_KEY),
                "ACCOUNT_TYPE_NOT_ALLOWED", "HAY-ERROR", "TIPO DE CUENTA NO PERMITIDO");
